{
  "id": "V055",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "반복 문의를 줄이려는 목적이 BUSINESS에 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "조건·서류를 설명하고 답을 확정하기 어려운 문의를 인사 담당자에게 넘김."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건과 제출 서류가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "직원의 질문과 현재 게시된 사내 규정을 입력으로 삼음."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "질문에 맞는 조건과 서류 안내 및 어려운 문의의 인계가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "승인과 인사시스템 정보 변경을 포함하지 않는다는 제약이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능 추가가 확인되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "직원 질문에 응답하고 규정으로 답하기 어려운 문의는 인사 담당자에게 넘기는 역할이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "승인과 인사시스템 정보 변경은 범위에서 제외됨. 인사 담당자에게 문의를 넘기는 것은 보존되며, 담당자가 매번 승인하거나 별도 조치를 수행한다고 단정하지 않음."
}
